import six
import collections
from IQCommon import pandas as pd
from IQCommon.util.common_func import asset_common
from IQEngine.api.api_base import engine_instance
from IQEngine.const import AssetType, MARKET_ALIAS, RunType
from IQEngine.core.events import EventEnum
from IQEngine.utils.exception import IQInvalidArgument
from IQEngine.utils.i18n import get_local_text as _
class AssetMixin(object):
    __doc__ = '\n    Asset的查询接口类\n    '
    def __init__(self, assets):
        self.assets = assets
        self._assets = collections.OrderedDict()
        self._assets_typed_dict = {}
        self._assets_types = {}
        self._assets_types_tuple = tuple()
        self.assets_handle()
        self.engine = engine_instance()
        self.engine.event_bus.append_listener(EventEnum.PRE_TRADING_UPDATE, self.asset_reload)
    def sw_industry(self, code):
        return [v.symbol for v in self._assets.values() if v.type == AssetType.STOCK and v.SW_industry_code == code]
    def zjh_industry_code(self, code):
        return [v.symbol for v in self._assets.values() if v.type == AssetType.STOCK and v.ZJH_industry_code == code]
    def industry_code(self, code):
        return (self.sw_industry(code) + self.zjh_industry_code(code))
    def get_all_assets(self, types=None, dt=None):
        if (types is not None):
            if isinstance(types, list):
                asset_list = []
                for asset_type in types:
                    asset_list += self._get_assets_with_type(asset_type)
            else:
                asset_list = self._get_assets_with_type(types)
        else:
            asset_list = self._assets.values()
        if (dt is not None):
            pd.Timestamp(dt)
            asset_list = filter(lambda i: i.listed_date.date() <= dt.date() <= i.delisted_date.date(), asset_list)
        if (not isinstance(asset_list, list)):
            asset_list = list(asset_list)
        return asset_list
    def get_assets(self, asset_or_symbols):
        if isinstance(asset_or_symbols, six.string_types):
            symbol = asset_or_symbols.upper()
            asset = self._assets.get(symbol, None)
            if (asset is None):
                for alias in MARKET_ALIAS:
                    if symbol.endswith(alias):
                        symbol = (symbol[:-len(alias)] + MARKET_ALIAS[alias])
                        break
                asset = self._assets.get(symbol, None)
            return asset
        elif isinstance(asset_or_symbols, self._assets_types_tuple):
            return asset_or_symbols
        elif isinstance(asset_or_symbols, list):
            return [i for i in asset_or_symbols if i]
            return [self.get_assets(sid) for sid in asset_or_symbols]
        else:
            raise KeyError(_('标的：{asset}类型：{asset.__class__}不支持，参数类型应当为：string/BaseAsset/list').format(asset=asset_or_symbols))
    def get_future_contracts(self, trade_code, date):
        date = date.replace(hour=0, minute=0, second=0)
        futures = [v for o, v in six.iteritems(self._assets) if v.type == 'Future' and v.trade_code == trade_code and not o.endswith('88') and not o.endswith('99')]
        if (not futures):
            return []
        else:
            return sorted(i.symbol for i in futures)
    def _get_assets_with_type(self, asset_type):
        if isinstance(asset_type, six.string_types):
            asset_type = AssetType(asset_type.upper())
        elif isinstance(asset_type, AssetType):
            pass
        else:
            return []
        return self._assets_typed_dict[asset_type.value]
    def is_valid_asset(self, asset, asset_type=None):
        if (asset_type is None):
            asset_type_class = self._assets_types_tuple
        elif isinstance(asset_type, six.string_types):
            asset_type_class = self._assets_types.get(asset_type, None)
            if (asset_type_class is None):
                raise IQInvalidArgument(_('标的校验类型{}不存在').format(asset_type))
            return isinstance(asset, asset_type_class)
        elif isinstance(asset_type, collections.abc.Iterable):
            asset_type_class = tuple(self._assets_types[a_type] for a_type in asset_type if a_type in self._assets_types)
            if (not asset_type_class):
                raise IQInvalidArgument(_('标的校验类型{}不存在').format(asset_type))
        else:
            raise IQInvalidArgument(_('标的校验类型{}不存在').format(asset_type))
    def assets_handle(self):
        for asset_type_list in self.assets:
            if (len(asset_type_list) == 0):
                continue
            asset_type = asset_type_list[0].type
            self._assets_types[asset_type] = type(asset_type_list[0])
            self._assets_typed_dict[asset_type] = asset_type_list
            for asset in asset_type_list:
                self._assets[asset.symbol.upper()] = asset
        else:
            self._assets_types_tuple = tuple(self._assets_types.values())
    @staticmethod
    def asset_reload(event=None):
        asset_common.update_assets()
